using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditorInternal;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class FinishPerformanceValidation {
 const string Root="Docs/Measurements/2026-10-03-performance/";
 public static string Finish(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var original=JObject.Parse(File.ReadAllText(Root+"editor-original.json"));Environment.SetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT",null);Application.runInBackground=(bool)original["runInBackground"];ProfilerDriver.enabled=(bool)original["profilerEnabled"];ProfilerDriver.profileEditor=false;AssetDatabase.SaveAssets();var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var report=new JObject{{"scene",EditorSceneManager.GetActiveScene().path},{"playing",Application.isPlaying},{"dirty",EditorSceneManager.GetActiveScene().isDirty},{"saveOverrideCleared",Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")==null},{"runInBackground",Application.runInBackground},{"profilerEnabled",ProfilerDriver.enabled},{"testControlsSavedActive",h.Buttons.Where(b=>new[]{"infinite-resources","quick-day","quick-night"}.Contains(b.Id)).All(b=>b.View.gameObject.activeSelf)}};File.WriteAllText(Root+"final-editor-state.json",report.ToString());return report.ToString();}
}